#home-jumbotron {
  display: none;
}
#countdown-wrapper {
  text-align: center;
  font-weight: bold;
  background-color: #444444;
  color: #fff;
  margin-bottom: 20px;
}
#countdown-wrapper h3 {
  background-color: #000;
  color: #fff;
  padding: 10px 20px;
}
#countdown-timer {
  padding-bottom: 10px;
}
#countdown-timer p {
  font-size: 20px;
}
#countdown-timer::after {
  content: "";
  clear: both;
  display: table;
}
#countdown-wrapper ol {
  margin: 0;
  padding: 0;
  list-style-type: none;
}
#countdown-wrapper li {
  float: left;
  width: 33%;
  border-right: 1px solid #fff;
}
#countdown-wrapper li.countdown-no-border {
  border-right: none;
}
#countdown-days, #countdown-hours, #countdown-minutes {
  font-size: 32px;
}






